  "request" : "Launch",
  "debugServer" : 6006, // port should match the Debug Adapter port in the Godot Editor project settings.
  "scene" : "main", // main, current, res://path/to/file.tscn

  // "playArgs" : [ "--editor" ], // debugging a tool script
